# Accept a single int OR multiple IDs via tuple/list/set/comma-separated string.
def _normalize_owner_ids(raw):
    vals = []
    if isinstance(raw, int):
        vals = [raw]
    elif isinstance(raw, (tuple, list, set)):
        for v in raw:
            try:
                iv = int(str(v).strip())
                if iv > 0:
                    vals.append(iv)
            except Exception:
                pass
    elif isinstance(raw, str):
        for part in raw.replace(' ', '').split(','):
            if not part:
                continue
            try:
                iv = int(part)
                if iv > 0:
                    vals.append(iv)
            except Exception:
                pass
    dedup = []
    seen = set()
    for v in vals:
        if v not in seen:
            dedup.append(v)
            seen.add(v)
    return dedup

