def list_staff_ids() -> List[int]:
    conn = db_connect()
    cur = conn.cursor()
    cur.execute("SELECT user_id FROM users WHERE role IN ('OWNER','ADMIN')")
    rows = cur.fetchall()
    conn.close()
    ids = [int(r["user_id"]) for r in rows]
    for _oid in OWNER_IDS:
        if _oid not in ids:
            ids.append(_oid)
    return sorted(set(ids))


